def format_gsm8k_prompt(
    template_id: int,
    question: str,
    few_shot_examples: list[dict] | None = None,
) -> str:
    """Build a GSM8K prompt with optional few-shot CoT examples."""
    tmpl = GSM8K_TEMPLATES.get(template_id, GSM8K_TEMPLATES[1])
    parts = [tmpl["system"]]
